import { z } from "zod";

/**
 * Response schemas for the core domain entities.
 *
 * These exist so the API's *outputs* are described by the same kind of
 * checked source as its inputs. Until now only request bodies had zod schemas,
 * which meant the OpenAPI document could describe what the API accepted but had
 * nothing truthful to say about what it returned — so every consumer, including
 * our own frontend, hand-declared the response types and they drifted.
 *
 * Deriving frontend types from these (see frontend/src/types/api.generated.ts,
 * regenerated by `npm run generate:types`) makes a rename on the server a
 * compile error in the client rather than a runtime undefined.
 *
 * Two deliberate choices:
 *
 *   - `_id` is `z.string()`, not an ObjectId type. By the time JSON reaches a
 *     client the id is a string, and typing it as one prevents the classic
 *     `ObjectId cannot be assigned to string` mismatch.
 *   - `createdAt`/`updatedAt` are ISO strings, not `Date`. JSON has no Date.
 *
 * Fields are `.passthrough()` where the entity is returned with populated
 * references, because a strict schema would report a false error for a field
 * the server genuinely adds.
 */

/** Mongo ObjectId as it appears in JSON. */
export const objectId = z.string().regex(/^[a-f0-9]{24}$/i, "Not a Mongo id");

export const isoDateTime = z.string().describe("ISO 8601 timestamp");

// ── Shared sub-documents ────────────────────────────────────────────────────

/** A user as embedded in another entity's response (never the full document). */
export const userRefSchema = z
  .object({
    _id: objectId,
    name: z.string(),
    profileImageUrl: z.string().optional(),
    role: z.enum(["patient", "doctor", "staff", "admin"]).optional(),
    phone: z.string().optional(),
    email: z.string().optional(),
  })
  .passthrough();

// ── Review ──────────────────────────────────────────────────────────────────

export const reviewSchema = z
  .object({
    _id: objectId,
    /**
     * Populated with `{ _id, name, profileImageUrl }` by the list endpoint, so
     * it is an embedded user here rather than an id — while `doctorId` stays a
     * bare id. That asymmetry is real (only one side is populated to keep the
     * response small) and is why the types cannot be simplified by eye.
     */
    patientId: z
      .object({
        _id: objectId,
        name: z.string(),
        profileImageUrl: z.string().optional(),
      })
      .passthrough(),
    doctorId: objectId,
    rating: z.number().int().min(1).max(5),
    /** Defaults to "" in the schema, so always present. */
    comment: z.string(),
    createdAt: isoDateTime,
    updatedAt: isoDateTime,
  })
  .passthrough();

/**
 * Per-doctor totals, computed by the list endpoint so the UI does not have to
 * join against the doctors endpoint. Note `avgRating` and `distribution`: the
 * obvious names would be `averageRating` and `buckets`, and the frontend used to
 * guess — this schema pins the real ones.
 */
export const reviewSummarySchema = z.object({
  avgRating: z.number().min(0).max(5),
  totalReviews: z.number().int().nonnegative(),
  /** Review count per star, keyed 1..5. */
  distribution: z.record(z.string(), z.number().int().nonnegative()),
});

export const reviewListResponseSchema = z.object({
  reviews: z.array(reviewSchema),
  summary: reviewSummarySchema,
  /**
   * Whether the signed-in patient may rate this doctor. Computed up front from
   * the same completed-visit rule upsertReview enforces, so the UI can explain
   * why the form is unavailable instead of letting a patient fill it in and hit
   * a 403.
   */
  canReview: z.boolean(),
  myReview: reviewSchema.nullable(),
});

// ── Report ──────────────────────────────────────────────────────────────────

/**
 * A file inside a report.
 *
 * The storage fields are genuinely optional and mutually exclusive: an image
 * has `url`/`publicId` (Cloudinary), a PDF has `storageId` (GridFS). That split
 * is why this shape has three optional fields rather than one required URL —
 * and it is the sort of thing a hand-written interface tends to get wrong.
 */
export const reportFileSchema = z.object({
  url: z.string().optional(),
  publicId: z.string().optional(),
  storageId: z.string().optional(),
  storage: z.enum(["cloudinary", "gridfs"]).optional(),
  name: z.string(),
  mimeType: z.string(),
  size: z.number(),
  resourceType: z.string().optional(),
});

export const reportSchema = z
  .object({
    _id: objectId,
    patientId: userRefSchema,
    uploadedBy: userRefSchema,
    title: z.string(),
    category: z.enum(["lab", "imaging", "test", "other"]),
    description: z.string().optional(),
    consultationId: objectId.optional(),
    files: z.array(reportFileSchema),
    createdAt: isoDateTime,
    updatedAt: isoDateTime,
  })
  .passthrough();

/** `GET /report` returns the reports array directly, not a wrapper object. */
export const reportListSchema = z.array(reportSchema);

// ── Notification ────────────────────────────────────────────────────────────

/**
 * Mirrors NOTIFICATION_TYPES in db/models/notification.model.ts.
 *
 * Worth stating plainly: an earlier draft of this file invented a plausible
 * looking set (`appointment`, `report`, `system`, …) with `userId`/`message`/
 * `read` fields. The real model has always used `recipientId`/`body`/`readAt`
 * and a much shorter type list. The invented version would have typechecked
 * happily and then rejected every real notification — which is why these
 * schemas are now verified against live responses in tests/api/responseSchemas.test.ts
 * rather than trusted because they look right.
 */
export const notificationTypeSchema = z.enum([
  "leave-conflict",
  "appointment-status",
  "appointment-rescheduled",
  "follow-up-due",
]);

export const notificationSchema = z
  .object({
    _id: objectId,
    recipientId: objectId,
    type: notificationTypeSchema,
    title: z.string(),
    body: z.string(),
    link: z.string().optional(),
    appointmentId: objectId.optional(),
    /** null until read; the field is always present. */
    readAt: z.string().nullable(),
    createdAt: isoDateTime,
  })
  .passthrough();

// ── Clinic ──────────────────────────────────────────────────────────────────

export const clinicDayHoursSchema = z.object({
  /** Weekday as a 0-6 index (0 = Sunday), matching the mongoose model. */
  day: z.number().int().min(0).max(6),
  isOpen: z.boolean(),
  slots: z.array(z.string()).optional(),
});

/**
 * What the public settings endpoint actually returns.
 *
 * This is deliberately NOT the ClinicSettings document. That one holds `_id`,
 * `slots` and `workingHours` for internal use; the public endpoint projects a
 * narrower, deliberately safe view — contact details, opening hours, and a
 * `today` block carrying the live open/closed state.
 *
 * Worth stating because the first draft of this schema described the internal
 * document, which looked plausible and failed on the first field.
 */
export const publicClinicSettingsSchema = z
  .object({
    clinicName: z.string(),
    address: z.string(),
    phone: z.string(),
    email: z.string(),
    about: z.string(),
    /** How far ahead a patient may still cancel without penalty. */
    cancellationWindowMinutes: z.number(),
    hours: z.array(clinicDayHoursSchema),
    today: z
      .object({
        day: z.number().int().min(0).max(6),
        isOpen: z.boolean(),
        slots: z.array(z.string()),
        isOpenNow: z.boolean(),
        opensAt: z.string().nullable(),
        closesAt: z.string().nullable(),
        nextChangeAt: z.string().nullable(),
      })
      .passthrough(),
  })
  .passthrough();

export const clinicBlockoutSchema = z
  .object({
    _id: objectId,
    date: z.string(),
    endDate: z.string().optional(),
    reason: z.string().optional(),
    doctorId: objectId.optional(),
    scope: z.enum(["clinic", "doctor"]).optional(),
    createdAt: isoDateTime.optional(),
  })
  .passthrough();

// ── Directory ───────────────────────────────────────────────────────────────

/**
 * A user as the *admin* directory returns it: credentials stripped, plus
 * whatever role-specific profile the role carries.
 *
 * `role` is required here because getAllUsers selects it explicitly. The patient
 * directory does not — its projection omits `role` entirely (every row is a
 * patient, so the field would be redundant), which is why
 * `patientDirectoryEntrySchema` below treats it as optional.
 */
export const userSummarySchema = z
  .object({
    _id: objectId,
    name: z.string(),
    email: z.string(),
    phone: z.string(),
    role: z.enum(["patient", "doctor", "staff", "admin"]),
    gender: z.string().optional(),
    dateOfBirth: z.string().optional(),
    bloodGroup: z.string().optional(),
    profileImageUrl: z.string().optional(),
    isActive: z.boolean().optional(),
    /** Present on doctor profiles only. */
    doctorProfile: z
      .object({
        specialization: z.string().optional(),
        qualification: z.string().optional(),
        experience: z.number().optional(),
        consultationFee: z.number().optional(),
        averageRating: z.number().optional(),
        totalReviews: z.number().optional(),
      })
      .passthrough()
      .optional(),
  })
  .passthrough();

/**
 * The patient directory's narrower projection — no `role`, no `isActive`,
 * because the query already filtered on both and the UI never needed them.
 */
export const patientDirectoryEntrySchema = userSummarySchema.omit({
  role: true,
  isActive: true,
});

/** A dependent, which has no login of its own and therefore no email. */
export const familyMemberSchema = z
  .object({
    _id: objectId,
    name: z.string(),
    phone: z.string(),
    gender: z.string().optional(),
    dateOfBirth: z.string().optional(),
    bloodGroup: z.string().optional(),
    accountType: z.literal("dependent").optional(),
    shareCode: z.string().optional(),
    guardians: z.array(objectId).optional(),
  })
  .passthrough();

/** `{ notifications, unreadCount }` as the notification list endpoint returns. */
export const notificationListSchema = z.array(notificationSchema);

// ── Leave ───────────────────────────────────────────────────────────────────

export const leaveRecordSchema = z
  .object({
    _id: objectId,
    doctorId: objectId,
    fromDate: z.string(),
    toDate: z.string(),
    reason: z.string().optional(),
    status: z.enum(["pending", "approved", "rejected"]),
    createdAt: isoDateTime.optional(),
  })
  .passthrough();

// ── Appointment ─────────────────────────────────────────────────────────────

export const appointmentStatusSchema = z.enum([
  "pending",
  "arrived",
  "completed",
  "cancelled",
  "no-show",
]);

export const appointmentSchema = z
  .object({
    _id: objectId,
    patientId: userRefSchema.optional(),
    doctorId: userRefSchema.optional(),
    appointmentDate: z.string(),
    timeSlot: z.string(),
    durationInMinutes: z.number().optional(),
    status: appointmentStatusSchema,
    consultationType: z.string().optional(),
    checkedInAt: isoDateTime.optional(),
    intakeDetails: z.record(z.string(), z.unknown()).optional(),
    createdAt: isoDateTime.optional(),
  })
  .passthrough();

// ── Envelope helpers ────────────────────────────────────────────────────────

/** Wrap a payload in the `{ success, message, data }` envelope every route returns. */
export const envelope = <T extends z.ZodTypeAny>(data: T) =>
  z.object({ success: z.boolean(), message: z.string(), data });